:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #fdcb6e;
  --text: #f0f0f0;
  --card-back: #3a3a5c;
  --card-border: #4a4a6a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width: 600px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.stats {
  font-size: 1.125rem;
  color: var(--text);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  width: 100%;
  aspect-ratio: 1;
  max-width: 400px;
}

.card {
  aspect-ratio: 1;
  background: var(--card-back);
  border: 2px solid var(--card-border);
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.2s, background-color 0.2s, border-color 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  user-select: none;
  position: relative;
  transform-style: preserve-3d;
}

.card:hover:not(.matched):not(.flipped) {
  transform: scale(1.05);
  border-color: var(--accent);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.95);
}

.card.flipped {
  background: var(--primary);
  border-color: var(--accent);
}

.card.matched {
  background: var(--accent);
  border-color: var(--accent);
  cursor: default;
  opacity: 0.7;
}

.card .card-color {
  display: none;
  width: 60%;
  height: 60%;
  border-radius: 50%;
}

.card.flipped .card-color,
.card.matched .card-color {
  display: block;
}

.win-message {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--accent);
  text-align: center;
}

.new-game-btn {
  background: var(--primary);
  color: var(--text);
  border: none;
  border-radius: 8px;
  padding: 12px 32px;
  font-size: 1.125rem;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.new-game-btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .game-board {
    gap: 8px;
  }
  .new-game-btn {
    padding: 10px 24px;
    font-size: 1rem;
  }
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#1abc9c', '#e67e22', '#e84393'
];

const board = document.getElementById('game-board');
const moveCountEl = document.getElementById('move-count');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game-btn');

let cards = [];
let flippedCards = [];
let matchedPairs = 0;
let moves = 0;
let lockBoard = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createCard(color, index) {
  const card = document.createElement('button');
  card.type = 'button';
  card.className = 'card';
  card.setAttribute('aria-label', 'Hidden card');
  card.dataset.color = color;
  card.dataset.index = index;

  const colorCircle = document.createElement('span');
  colorCircle.className = 'card-color';
  colorCircle.style.backgroundColor = color;
  card.appendChild(colorCircle);

  card.addEventListener('click', () => flipCard(card));
  return card;
}

function flipCard(card) {
  if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.setAttribute('aria-label', 'Flipped card');
  flippedCards.push(card);

  if (flippedCards.length === 2) {
    moves++;
    moveCountEl.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  const [a, b] = flippedCards;
  if (a.dataset.color === b.dataset.color) {
    a.classList.add('matched');
    b.classList.add('matched');
    a.setAttribute('aria-label', 'Matched card');
    b.setAttribute('aria-label', 'Matched card');
    matchedPairs++;
    flippedCards = [];
    if (matchedPairs === COLORS.length) {
      winMessage.hidden = false;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.setAttribute('aria-label', 'Hidden card');
      b.setAttribute('aria-label', 'Hidden card');
      flippedCards = [];
      lockBoard = false;
    }, 800);
  }
}

function initGame() {
  board.innerHTML = '';
  flippedCards = [];
  matchedPairs = 0;
  moves = 0;
  lockBoard = false;
  moveCountEl.textContent = 'Moves: 0';
  winMessage.hidden = true;

  const deck = [...COLORS, ...COLORS];
  shuffle(deck);

  deck.forEach((color, i) => {
    const card = createCard(color, i);
    board.appendChild(card);
  });
}

newGameBtn.addEventListener('click', initGame);

initGame();
